using System;

class Program
{
    static void Main()
    {
        // int x = null; // Compile error: value types cannot be null

        // Add '?' to make it nullable
        int? age = null;
        double? price = 29.99;
        bool? isMember = null;
        DateTime? lastLogin = null;

        // Check if a value is present using HasValue
        if (age.HasValue)
        {
            Console.WriteLine($"Age is {age.Value}");
        }
        else
        {
            Console.WriteLine("Age is unknown (null)");
        }

        // The Value property throws if the value is null
        // age.Value; // Throws InvalidOperationException!

        // GetValueOrDefault returns a fallback when null
        int safeAge = age.GetValueOrDefault();        // Returns 0 for int
        int defaultAge = age.GetValueOrDefault(18);    // Returns 18

        Console.WriteLine($"safeAge = {safeAge}, defaultAge = {defaultAge}");
    }
}

using System;

class Program
{
    static void Main()
    {
        string? input = GetUserInput(); // Might be null

        // Null-coalescing: provide a default if null
        string displayName = input ?? "Anonymous";
        Console.WriteLine($"Hello, {displayName}!");

        // Null-conditional: safely access Length without a crash
        int? nameLength = input?.Length;
        Console.WriteLine($"Name length: {nameLength}");

        // Null-coalescing assignment: only set if currently null
        string? cached = null;
        cached ??= LoadFromCache(); // Loads only if null
        Console.WriteLine($"Cached value: {cached}");

        // Chaining null-conditional and coalescing
        string? city = null;
        int population = city?.Length ?? 0; // If city is null, use 0
        Console.WriteLine($"Population placeholder: {population}");
    }

    static string? GetUserInput() => null; // Simulating missing input

    static string LoadFromCache() => "Cached Data";
}

