using System;

class UserProfile
{
    // 'string' without '?' means this must never be null
    public string UserName { get; set; }

    // 'string?' explicitly allows null
    public string? MiddleName { get; set; }

    // Return type is non-nullable — caller expects a real value
    public string GetDisplayName()
    {
        // Compiler knows UserName is non-null here
        return MiddleName != null
            ? $"{UserName} {MiddleName}"
            : UserName;
    }

    // Null-forgiving operator: suppress warning when you know it's not null
    public int GetNameLength(string? name)
    {
        // name?.Length returns int? (nullable)
        // name!.Length tells compiler: I know it's not null here
        return name!.Length;
    }
}

class Program
{
    static void Main()
    {
        UserProfile profile = new UserProfile
        {
            UserName = "Alice",
            MiddleName = "Marie"
        };

        Console.WriteLine(profile.GetDisplayName());
        Console.WriteLine($"Name length: {profile.GetNameLength(profile.UserName)}");
    }
}

