using System;

class Program
{
    static void Main()
    {
        string? input = LoadConfigValue();

        // input?.Length returns int? — we need a plain int
        // The ! suppresses the nullable warning because we validated it
        if (input != null)
        {
            int length = input!.Length; // Safe: we just checked
            Console.WriteLine($"Config value length: {length}");
        }
        else
        {
            Console.WriteLine("Config value was null.");
        }
    }

    static string? LoadConfigValue()
    {
        // Simulating a config file that might be missing
        return Environment.GetEnvironmentVariable("APP_NAME");
    }
}
